mapper.sql:
WHERE pa.is_deleted = 0


    AND pa.status = #{status}



    AND (
    pa.name LIKE CONCAT('%', #{keywords}, '%')
    OR pa.description LIKE CONCAT('%', #{keywords}, '%')
    )

mapper.select:
SELECT
FROM photo_album pa LEFT JOIN photo p ON p.album_id = pa.id AND p.is_deleted = 0
GROUP BY pa.id, pa.name, pa.description, pa.cover_url, pa.sort_order, pa.status, pa.created_at, pa.updated_at ORDER BY pa.sort_order ASC, pa.id ASC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM photo_album
WHERE name = #{name}


    AND id != #{excludeId}
